export type DialogError = {
    errorType: 'SAFETY_MODE' | 'RUNTIME' | string;
    errorCodes?: number[];
    safetyMode?: SafetyModeError;
};
export type LayerToken =
    | '--layer-error'
    | '--layer-popup'
    | '--layer-keyboard'
    | '--layer-notification'
    | '--layer-dropdown'
    | '--layer-modal'
    | '--layer-navigation'
    | '--layer-tooltip'
    | '--layer-tools'
    | '--layer-program-nodes'
    | '--layer-default'
    | '--layer-under';
export interface DialogConfig {
    // controlling layer of the dialog with a css variable
    backdropClass?: string;
    critical?: boolean; // If dialog is critical, and cannot be 'force closed'.
    disableClose?: boolean; // If dialog shouldn't have a close icon
    disableFocusTrap?: boolean; // Set to true for non-interactive overlays (e.g. a temporary blocking backdrop) whose content has no tabbable elements.
    error?: DialogError;
    hasBackdrop?: boolean;
    injector?: Injector;
    layer?: LayerToken;
    maxOpenDialogs?: number; // If dialog has limit on number of open dialogs.
    panelClass?: string;
    size?: DialogSizeType;
    type?: keyof typeof DIALOG_TYPES; // used to identify and categorize open dialogs, and decide which dialog to close when a close by type event is emitted.
    viewContainerRef?: ViewContainerRef;
}

export const DIALOG_KEYS = {
    LOCALSTORAGE: 'ur-portal-service',
    OPEN_EVENT: 'portalservice:open',
    CLOSE_EVENT: 'portalservice:close',
    UPDATE_EVENT: 'portalservice:update',
    CLOSE_BY_ID_EVENT: 'portalservice:close_own',
    CLOSE_BY_ERROR_TYPE_EVENT: 'portalservice:close_by_type',
    CLOSE_BY_TYPE_EVENT: 'portalservice:close_by_dialog_type',
    SAFETY_CLOSED_EVENT: 'portalservice:safety_closed',
} as const;

/**
 * Types if dialogs that can be used to identify the dialog and decide which dialog to close when a close by type event is emitted.
 * * USER: Dialogs that are used to display user related information, and opened by the user. Can be closed by the user.
 * * SYSTEM: Dialogs that are used to display system related information to the user, and maybe requires an action. These dialogs can be closed by the user and external control.
 * * SAFETY: Dialogs that are used to display safety related information to the user, and require immediate action.
 * * PROTECTIVE_STOP: Dialogs that are used to display protective stop related information to the user. These dialogs should be closed by the user after they have acknowledged the protective stop information.
 *  These dialogs should be closed by the user after they have acknowledged the safety information.
 *  Safety dialogs should be prioritized over other dialogs, and should not be closed by force close all function, as they require immediate attention from the user.
 */
export const DIALOG_TYPES = {
    USER: 'USER',
    SYSTEM: 'SYSTEM',
    SAFETY: 'SAFETY',
    PROTECTIVE_STOP: 'PROTECTIVE_STOP',
} as const;
