import { VirtualKeyboardLayout } from './ur-keyboard.model';

const layouts: Record<string, (positiveOnly: boolean) => VirtualKeyboardLayout> = {
    integer: (pos) => (pos ? 'numeric-fixed-positive' : 'numeric-fixed'),
    float: (pos) => (pos ? 'numeric-free-positive' : 'numeric-free'),
    string: () => 'alpha-numeric',
};
/**
 * Returns the appropriate virtual keyboard layout based on the provided value type and positivity requirement.
 */
export const getKeyboardLayout = (valueType: string | undefined, positiveOnly = false): VirtualKeyboardLayout =>
    (layouts[valueType?.toLowerCase() ?? ''] ?? (() => 'alpha-numeric'))(positiveOnly);
